<template>\n  <div class="chatbox-bg tw-flex tw-flex-col tw-w-full tw-h-full"\n    ref="rootComponentContainer"\n    data-edit-id="1">\n    \x3C!-- ======================= 导航栏 ======================= -->\n    <header v-if="(isSolo || content.isSolo) && dataEditable"\n      class="chatbox-navbar"\n      data-edit-id="2">\n      <div class="navbar-inner" data-edit-id="3">\n        <div class="navbar-left" data-edit-id="4">\n          <div class="navbar-logo"\n            :style="{ background: \'var(--muse-primary)\' }"\n            data-edit-id="5">\n            <span class="navbar-logo-text" data-edit-id="6">{{\n              icon || "✦"\n            }}</span>\n          </div>\n          <div class="navbar-title" data-edit-id="7">\n            <span class="navbar-title-text" data-edit-id="8">{{ title }}</span>\n            <span class="navbar-introduce" data-edit-id="9">{{\n              introduce\n            }}</span>\n          </div>\n        </div>\n        <div class="tw-flex tw-items-center" data-edit-id="103">\n          <button v-if="isLoggedIn"\n            type="button"\n            class="skill-config-btn"\n            title="配置消息操作（Skill）"\n            data-edit-id="117"\n            @click="openSkillConfig">\n            <i class="bi bi-sliders" data-edit-id="129"></i>\n            <span data-edit-id="130">Skill 配置</span>\n          </button>\n          <div appName="loginRegItem"\n            component="CardItem"\n            class="tw-opacity-100 refined-user-card"\n            :style="{\n              width: \'135px\',\n              marginLeft: \'15px\',\n              height: \'30px\',\n              borderLeft: \'solid 1px #ddd\',\n            }"\n            data-edit-id="104"></div>\n        </div>\n      </div>\n    </header>\n\n    \x3C!-- ======================= 消息区 ======================= -->\n    <main class="chatbox-main"\n      ref="scrollContainer"\n      @scroll="onScroll"\n      data-edit-id="14">\n      \x3C!-- 空状态 -->\n      <div v-if="messages.length === 0" class="chatbox-empty" data-edit-id="15">\n        <div class="empty-rune" data-edit-id="16">\n          <div class="empty-ring" data-edit-id="17"></div>\n          <i class="bi bi-chat-square-text empty-icon" data-edit-id="18"></i>\n        </div>\n        <h2 class="empty-title" data-edit-id="19">\n          {{ title || "你好，我是你的助手" }}\n        </h2>\n        <p class="empty-subtitle" data-edit-id="20">\n          {{ introduce || "有什么可以帮你的？" }}\n        </p>\n\n        <div class="empty-chips"\n          v-if="exampleList && exampleList.length"\n          data-edit-id="21">\n          <button v-for="(d, i) in exampleList"\n            :key="i"\n            class="empty-chip"\n            @click="useExample(d)"\n            data-edit-id="22">\n            <span class="chip-icon" data-edit-id="23">{{ d.icon || "✦" }}</span>\n            <span data-edit-id="24">{{ d.name || d.title }}</span>\n          </button>\n        </div>\n      </div>\n\n      \x3C!-- 消息列表 -->\n      <div v-else class="message-list" data-edit-id="25">\n        <article v-for="m in messages"\n          :key="m.id"\n          class="message-row"\n          :class="\n            m.role === \'user\' ? \'message-row--user\' : \'message-row--assistant\'\n          "\n          data-edit-id="26">\n          <div class="message-body" data-edit-id="29">\n            <div class="bubble"\n              :class="m.role === \'user\' ? \'bubble--user\' : \'bubble--assistant\'"\n              data-edit-id="33">\n              \x3C!-- 流式中的光标 -->\n              <template v-if="m.role === \'assistant\' && !m.content && m.streaming">\n                <span class="typing-dots"> <i></i><i></i><i></i> </span>\n              </template>\n              \x3C!-- 已渲染内容 -->\n              <div v-else\n                class="bubble-content"\n                v-html="renderMarkdown(m.content)"></div>\n              <span v-if="m.role === \'assistant\' && m.streaming && m.content"\n                class="stream-cursor"></span>\n            </div>\n\n            \x3C!-- 助手消息操作：可配置的动态按钮列表 / 下拉菜单 / 组合输入框 -->\n            <div v-if="\n                m.role === \'assistant\' &&\n                m.content &&\n                effectiveMessageActions.length\n              "\n              class="message-actions">\n              <div v-for="(item, idx) in effectiveMessageActions" :key="idx">\n                \x3C!-- 分隔线 -->\n                <span v-if="item.type === \'divider\'"\n                  class="action-divider"></span>\n\n                \x3C!-- 组合输入框 + 按钮 -->\n                <div v-else-if="isComboItem(item)" class="action-input-group">\n                  <input class="action-input"\n                    :type="item.inputType || \'text\'"\n                    :placeholder="item.placeholder || \'输入内容…\'"\n                    :maxlength="item.maxLength || undefined"\n                    :disabled="!!item.disabled"\n                    :title="item.tooltip"\n                    :data-key="item.key || \'\'"\n                    @input="onActionInput(m, item, $event)"\n                    @keydown.enter.stop.prevent="submitCombo(m, item, $event)"\n                    clearable />\n                  <button type="button"\n                    class="mini-btn mini-btn--combo"\n                    :disabled="!!item.disabled"\n                    :title="item.buttonTooltip || item.tooltip"\n                    @click="submitCombo(m, item, $event)">\n                    <i class="bi bi-chevron-right"></i>\n                  </button>\n                </div>\n\n                \x3C!-- 下拉菜单 -->\n                <div v-else-if="item.type === \'dropdown\'"\n                  class="action-dropdown"\n                  :class="{ open: isMenuOpen(m, item) }">\n                  <button type="button"\n                    class="mini-btn"\n                    :disabled="!!item.disabled"\n                    :title="item.tooltip"\n                    @click.stop="toggleActionMenu(m, item)">\n                    <i v-if="item.icon" :class="item.icon"></i>\n                    <span>{{ item.label || "更多" }}</span>\n                    <i class="bi bi-chevron-down action-arrow"></i>\n                  </button>\n                  <transition name="action-menu">\n                    <div v-if="isMenuOpen(m, item)" class="action-menu">\n                      <button v-for="child in item.children || []"\n                        :key="child.key || child.label"\n                        type="button"\n                        class="action-menu-item"\n                        :disabled="!!child.disabled"\n                        :title="child.tooltip"\n                        @click.stop="selectActionChild(m, item, child)">\n                        <i v-if="child.icon" :class="child.icon"></i>\n                        <span class="action-menu-label">{{ child.label }}</span>\n                      </button>\n                    </div>\n                  </transition>\n                </div>\n\n                \x3C!-- 普通按钮（默认类型） -->\n                <button v-else\n                  type="button"\n                  class="mini-btn"\n                  :class="{ \'mini-btn--active\': !!item.active }"\n                  :disabled="!!item.disabled"\n                  :title="item.tooltip"\n                  :data-key="item.key || \'\'"\n                  @click="\n                    dispatchMessageAction({\n                      type: \'click\',\n                      key: item.key,\n                      value: item.value,\n                      item: item,\n                      message: m,\n                    })\n                  ">\n                  <i v-if="item.icon" :class="item.icon"></i>\n                  <span>{{ item.label || "操作" }}</span>\n                </button>\n              </div>\n            </div>\n          </div>\n        </article>\n      </div>\n\n      \x3C!-- 回到底部 -->\n      <transition name="fade-up">\n        <button v-if="showScrollHint"\n          class="scroll-bottom-btn"\n          @click="scrollToBottom(true)">\n          <i class="bi bi-arrow-down"></i>\n        </button>\n      </transition>\n    </main>\n\n    \x3C!-- ======================= 子窗口层（同源内嵌 / 支持最小化 / 索引导航 / 可收起） ======================= -->\n    <transition name="child-win">\n      <section v-if="childWindows.length"\n        v-show="childPanelVisible"\n        class="child-window-layer"\n        data-edit-id="subwin"\n        style="\n          position: absolute;\n          right: 20px;\n          bottom: 168px;\n          width: min(740px, 64vw);\n          height: min(62vh, 620px);\n          min-height: 240px;\n          z-index: 50;\n          overflow: hidden;\n        ">\n        \x3C!-- 索引导航（标签栏）：仅展示当前激活窗口，其余窗口自动最小化 -->\n        <div class="child-window-nav"\n          data-edit-id="subwin-nav"\n          style="\n            position: absolute;\n            top: 0;\n            left: 0;\n            right: 0;\n            height: 42px;\n            box-sizing: border-box;\n          ">\n          <span class="child-nav-count" title="当前子窗口任务数">\n            <i class="bi bi-window-stack"></i>\n            <span>{{ childWindows.length }}</span>\n          </span>\n          <div class="child-nav-tabs">\n            <button v-for="(win, idx) in childWindows"\n              :key="win.id"\n              type="button"\n              class="child-nav-tab"\n              :class="{\n                active: win.id === activeChildId && !win.minimized,\n                minimized: win.minimized,\n              }"\n              :title="(win.minimized ? \'（已最小化）\' : \'\') + win.title"\n              @click="activateChildWindow(win.id)">\n              <span class="child-nav-index">{{ idx + 1 }}</span>\n              <span class="child-nav-title">{{ win.title }}</span>\n              <i v-if="win.minimized"\n                class="bi bi-window-stack child-nav-mini"></i>\n              <span class="child-nav-close"\n                title="关闭该窗口"\n                @click.stop="closeChildWindow(win.id)">×</span\n              >\n            </button>\n          </div>\n          <div class="child-nav-actions">\n            <button type="button"\n              class="child-nav-btn"\n              title="收起面板（保留任务，按钮恢复显示）"\n              @click="toggleChildPanel">\n              <i class="bi bi-chevron-down"></i>\n            </button>\n            <button type="button"\n              class="child-nav-btn child-nav-btn--danger"\n              title="关闭当前窗口"\n              :disabled="!activeChildWindow"\n              @click="closeChildWindow(activeChildId)">\n              <i class="bi bi-x-lg"></i>\n            </button>\n          </div>\n        </div>\n\n        \x3C!-- 子窗口内容：同一时刻仅激活且未最小化的窗口可见，其余保持挂载以保留状态 -->\n        <div v-for="win in childWindows"\n          v-show="win.id === activeChildId && !win.minimized"\n          :key="win.id"\n          class="child-window-body"\n          style="\n            position: absolute !important;\n            top: 42px !important;\n            left: 0 !important;\n            right: 0 !important;\n            bottom: 0 !important;\n            overflow: hidden !important;\n            background: #fff !important;\n          ">\n          <iframe :src="win.url"\n            class="child-window-frame"\n            style="\n              position: absolute !important;\n              top: 0 !important;\n              left: 0 !important;\n              right: 0 !important;\n              bottom: 0 !important;\n              width: 100% !important;\n              height: 100% !important;\n              border: none !important;\n              background: #fff !important;\n            "\n            frameborder="0"\n            allowfullscreen\n            sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-modals allow-downloads"></iframe>\n        </div>\n\n        \x3C!-- 全部最小化时的占位提示 -->\n        <div v-if="!activeChildWindow || activeChildWindow.minimized"\n          class="child-window-collapsed"\n          style="position: absolute; top: 42px; left: 0; right: 0; bottom: 0">\n          <i class="bi bi-window-stack child-collapsed-icon"></i>\n          <span>所有子窗口已最小化，点击上方索引恢复</span>\n        </div>\n      </section>\n    </transition>\n\n    \x3C!-- ======================= 输入区 ======================= -->\n    <footer class="chatbox-composer">\n      <div class="composer-inner">\n        \x3C!-- 子窗口控制按钮：固定在输入框右上方，常显任务数量，点击显示 / 隐藏浮窗 -->\n        <button v-if="childWindows.length"\n          type="button"\n          class="child-trigger-btn"\n          :class="{ \'child-trigger-btn--hidden\': !childPanelVisible }"\n          :title="\n            childPanelVisible\n              ? \'收起子窗口面板（\' + childWindows.length + \' 个任务）\'\n              : \'显示子窗口面板（\' + childWindows.length + \' 个任务）\'\n          "\n          @click="toggleChildPanel">\n          <i class="bi bi-window-stack"></i>\n          <span class="child-trigger-text">子窗口</span>\n          <span class="child-trigger-count">{{ childWindows.length }}</span>\n        </button>\n        <textarea ref="textarea"\n          v-model="draft"\n          class="composer-input"\n          :placeholder="inputPlaceholder"\n          rows="1"\n          @input="autoResize"\n          @keydown="onKeydown"></textarea>\n\n        <div class="composer-footer">\n          <div class="composer-hint">\n            <span v-if="isStreaming" class="streaming-hint">\n              <span class="hint-dot"></span>\n              {{ loadingText }}\n            </span>\n            <template v-else>\n              <span class="model-hint">\n                <i class="bi bi-command"></i>\n                {{ documentMeta.model }}/{{ documentMeta.apiName }}\n              </span>\n            </template>\n          </div>\n\n          <div class="composer-actions">\n            <button v-if="isStreaming"\n              class="send-btn send-btn--stop"\n              @click="stopStreaming">\n              <i class="bi bi-stop-fill"></i>\n              <span>停止</span>\n            </button>\n            <button v-else class="send-btn" :disabled="!canSend" @click="send">\n              <i class="bi bi-send-fill"></i>\n              <span>发送</span>\n            </button>\n          </div>\n        </div>\n      </div>\n    </footer>\n\n    \x3C!-- ======================= Skill 配置弹层 ======================= -->\n    <transition name="skill-config">\n      <div v-if="skillConfigVisible"\n        class="skill-config-mask"\n        @click.self="skillConfigVisible = false">\n        <div class="skill-config-panel">\n          <div class="skill-config-head">\n            <span class="skill-config-title"><i class="bi bi-sliders"></i> 配置 Skill 操作</span\n            >\n            <button type="button"\n              class="skill-config-close"\n              title="关闭"\n              @click="skillConfigVisible = false">\n              ×\n            </button>\n          </div>\n\n          <div class="skill-config-section-title">\n            已有 Skill（可修改名称 / ID）\n          </div>\n          <div v-if="skillActionItems.length" class="skill-config-list">\n            <div v-for="(item, idx) in skillActionItems"\n              :key="idx"\n              class="skill-config-item">\n              <i class="bi bi-stars skill-config-item-icon"></i>\n              <div class="skill-config-item-fields">\n                <input v-model="item.label"\n                  class="skill-config-edit"\n                  placeholder="Skill 名称"\n                  title="名称" />\n                <input v-model="item.id"\n                  class="skill-config-edit skill-config-edit--id"\n                  placeholder="Skill ID"\n                  title="ID" />\n              </div>\n              <button type="button"\n                class="skill-config-item-del"\n                title="删除该 Skill"\n                @click="removeSkill(item)">\n                ×\n              </button>\n            </div>\n          </div>\n          <div v-else class="skill-config-empty">\n            <i class="bi bi-inbox"></i>\n            <span>暂无 Skill 操作，请在下方新增</span>\n          </div>\n\n          <div class="skill-config-section-title">新增 Skill</div>\n          <div class="skill-config-add">\n            <label class="skill-config-field">\n              <span>名称</span>\n              <input v-model="skillDraft.name"\n                placeholder="如：生成 PPT"\n                @keydown.enter.prevent="addSkill" />\n            </label>\n            <label class="skill-config-field">\n              <span>ID</span>\n              <input v-model="skillDraft.id"\n                placeholder="Skill ID"\n                @keydown.enter.prevent="addSkill" />\n            </label>\n            <button type="button"\n              class="skill-config-add-btn"\n              :disabled="!canAddSkill"\n              @click="addSkill">\n              <i class="bi bi-plus-lg"></i> 新增\n            </button>\n          </div>\n\n          <div class="skill-config-footer">\n            <button type="button"\n              class="skill-config-cancel-btn"\n              @click="skillConfigVisible = false">\n              取消\n            </button>\n            <button type="button"\n              class="skill-config-confirm-btn"\n              @click="confirmSkillConfig">\n              确认\n            </button>\n          </div>\n        </div>\n      </div>\n    </transition>\n  </div>\n</template>\n\n<style scoped>\n/* ============================================\n   DESIGN TOKENS — Muse · 极简 · 精致\n   ============================================ */\n* {\n  --muse-primary: #0066cc;\n  --muse-primary-hover: #0052a3;\n  --muse-primary-active: #004c99;\n  --muse-primary-soft: rgba(0, 102, 204, 0.08);\n  --muse-primary-ring: rgba(0, 102, 204, 0.16);\n\n  --muse-bg: #eef3f0;\n  --muse-card: #f6f9f7;\n\n  --muse-text: #0f172a;\n  --muse-text-secondary: #475569;\n  --muse-text-tertiary: #94a3b8;\n\n  --muse-border: rgba(15, 23, 42, 0.08);\n  --muse-border-strong: rgba(15, 23, 42, 0.14);\n\n  --glass-bg: rgba(255, 255, 255, 0.72);\n  --glass-shadow: 0 1px 2px rgba(15, 23, 42, 0.04),\n    0 8px 24px rgba(15, 23, 42, 0.06);\n  --glass-shadow-hover: 0 2px 4px rgba(15, 23, 42, 0.05),\n    0 12px 32px rgba(15, 23, 42, 0.09);\n\n  --radius-card: 18px;\n  --radius-control: 12px;\n\n  --font-system: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI",\n    "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", Arial, sans-serif;\n}\n\n/* ============================================\n   全局背景 — 冰川灰 + 点阵纹理\n   ============================================ */\n.chatbox-bg {\n  position: relative;\n  font-family: var(--font-system);\n  color: var(--muse-text);\n  background-color: var(--muse-bg);\n  background-image: radial-gradient(\n      ellipse 70% 55% at 15% 0%,\n      rgba(0, 102, 204, 0.06) 0%,\n      transparent 55%\n    ),\n    radial-gradient(\n      ellipse 55% 45% at 100% 100%,\n      rgba(0, 102, 204, 0.04) 0%,\n      transparent 55%\n    ),\n    radial-gradient(\n      circle at 1px 1px,\n      rgba(148, 163, 184, 0.22) 1px,\n      transparent 0\n    );\n  background-size: auto, auto, 26px 26px;\n  overflow: hidden;\n}\n\n.chatbox-bg::before {\n  content: "";\n  position: absolute;\n  inset: 0;\n  background-image: linear-gradient(\n      to right,\n      rgba(0, 102, 204, 0.03) 1px,\n      transparent 1px\n    ),\n    linear-gradient(to bottom, rgba(0, 102, 204, 0.03) 1px, transparent 1px);\n  background-size: 84px 84px;\n  pointer-events: none;\n  z-index: 0;\n}\n\n/* ============================================\n   导航栏\n   ============================================ */\n.chatbox-navbar {\n  position: relative;\n  z-index: 10;\n  padding: 14px 20px 12px;\n}\n\n.navbar-inner {\n  max-width: 880px;\n  margin: 0 auto;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-bottom: 12px;\n  border-bottom: 1px solid transparent;\n  background-image: linear-gradient(\n    90deg,\n    transparent 0%,\n    rgba(0, 102, 204, 0.22) 30%,\n    rgba(0, 102, 204, 0.22) 70%,\n    transparent 100%\n  );\n  background-repeat: no-repeat;\n  background-position: bottom;\n  background-size: 100% 1px;\n}\n\n.navbar-left {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-width: 0;\n}\n\n.navbar-logo {\n  width: 38px;\n  height: 38px;\n  border-radius: 11px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #fff;\n  box-shadow: 0 2px 6px rgba(0, 102, 204, 0.32),\n    inset 0 1px 0 rgba(255, 255, 255, 0.2);\n  flex-shrink: 0;\n}\n\n.navbar-logo-text {\n  font-size: 17px;\n  font-weight: 700;\n  line-height: 1;\n}\n\n.navbar-title {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.navbar-title-text {\n  font-size: 16px;\n  font-weight: 600;\n  color: var(--muse-text);\n  letter-spacing: 0.01em;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.navbar-introduce {\n  font-size: 12px;\n  color: var(--muse-text-secondary);\n  margin-top: 2px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.navbar-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.ghost-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: #fff;\n  border: 1px solid var(--muse-border-strong);\n  color: var(--muse-text-secondary);\n  border-radius: 10px;\n  font-size: 13px;\n  font-weight: 500;\n  font-family: var(--font-system);\n  padding: 8px 14px;\n  cursor: pointer;\n  transition: all 0.18s ease;\n}\n\n.ghost-btn:hover {\n  border-color: var(--muse-primary);\n  color: var(--muse-primary);\n  transform: translateY(-1px);\n  box-shadow: 0 3px 10px rgba(0, 102, 204, 0.14);\n}\n\n/* ============================================\n   消息区\n   ============================================ */\n.chatbox-main {\n  position: relative;\n  z-index: 1;\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 12px 20px 20px;\n  scroll-behavior: smooth;\n}\n\n.chatbox-main::-webkit-scrollbar {\n  width: 6px;\n}\n\n.chatbox-main::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n.chatbox-main::-webkit-scrollbar-thumb {\n  background: rgba(15, 23, 42, 0.14);\n  border-radius: 6px;\n}\n\n.chatbox-main::-webkit-scrollbar-thumb:hover {\n  background: var(--muse-primary);\n}\n\n/* 空状态 */\n.chatbox-empty {\n  max-width: 640px;\n  margin: 0 auto;\n  padding: 60px 0 40px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n}\n\n.empty-rune {\n  position: relative;\n  width: 96px;\n  height: 96px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin-bottom: 20px;\n}\n\n.empty-ring {\n  position: absolute;\n  inset: 0;\n  border-radius: 50%;\n  border: 1.5px solid transparent;\n  border-top-color: var(--muse-primary);\n  border-right-color: rgba(0, 102, 204, 0.2);\n  animation: spin 6s linear infinite;\n  box-shadow: 0 0 18px rgba(0, 102, 204, 0.12);\n}\n\n.empty-icon {\n  font-size: 30px;\n  color: var(--muse-primary);\n  filter: drop-shadow(0 0 10px rgba(0, 102, 204, 0.35));\n}\n\n@keyframes spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n.empty-title {\n  font-size: 22px;\n  font-weight: 600;\n  color: var(--muse-text);\n  margin: 0 0 8px;\n  letter-spacing: -0.01em;\n}\n\n.empty-subtitle {\n  font-size: 14px;\n  color: var(--muse-text-secondary);\n  margin: 0 0 24px;\n}\n\n.empty-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  justify-content: center;\n}\n\n.empty-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 8px 14px;\n  background: rgba(255, 255, 255, 0.7);\n  border: 1px solid var(--muse-border);\n  color: var(--muse-text-secondary);\n  border-radius: 999px;\n  font-size: 13px;\n  font-weight: 500;\n  font-family: var(--font-system);\n  cursor: pointer;\n  backdrop-filter: blur(8px);\n  transition: all 0.18s ease;\n}\n\n.empty-chip:hover {\n  background: #fff;\n  border-color: var(--muse-primary);\n  color: var(--muse-primary);\n  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.14);\n  transform: translateY(-1px);\n}\n\n.chip-icon {\n  filter: grayscale(40%);\n  transition: filter 0.2s ease;\n}\n\n.empty-chip:hover .chip-icon {\n  filter: grayscale(0%);\n}\n\n/* 消息列表 */\n.message-list {\n  max-width: 880px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n.message-row {\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n}\n\n.message-row--user {\n  flex-direction: row-reverse;\n}\n\n.avatar {\n  width: 34px;\n  height: 34px;\n  border-radius: 10px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  font-size: 15px;\n}\n\n.avatar--assistant {\n  background: var(--muse-primary);\n  color: #fff;\n  font-weight: 700;\n  box-shadow: 0 2px 6px rgba(0, 102, 204, 0.28);\n}\n\n.avatar--user {\n  background: #fff;\n  color: var(--muse-text-secondary);\n  border: 1px solid var(--muse-border);\n  font-size: 18px;\n}\n\n.message-body {\n  max-width: calc(100% - 60px);\n  display: flex;\n  flex-direction: column;\n}\n\n.message-row--user .message-body {\n  align-items: flex-end;\n}\n\n.message-meta {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin-bottom: 5px;\n  padding: 0 2px;\n}\n\n.message-row--user .message-meta {\n  flex-direction: row-reverse;\n}\n\n.message-name {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--muse-text-secondary);\n}\n\n.message-time {\n  font-size: 11px;\n  color: var(--muse-text-tertiary);\n}\n\n.bubble {\n  position: relative;\n  padding: 12px 16px;\n  font-size: 14px;\n  line-height: 1.7;\n  word-break: break-word;\n}\n\n.bubble--assistant {\n  background: var(--glass-bg);\n  border: 1px solid var(--muse-border);\n  border-radius: 4px var(--radius-card) var(--radius-card) var(--radius-card);\n  box-shadow: var(--glass-shadow);\n  backdrop-filter: saturate(160%) blur(14px);\n  -webkit-backdrop-filter: saturate(160%) blur(14px);\n  color: var(--muse-text);\n}\n\n.bubble--user {\n  background: var(--muse-primary);\n  color: #fff;\n  border-radius: var(--radius-card) 4px var(--radius-card) var(--radius-card);\n  box-shadow: 0 2px 8px rgba(0, 102, 204, 0.28);\n}\n\n.bubble-content {\n  overflow-wrap: anywhere;\n}\n\n/* 流式光标 */\n.stream-cursor {\n  display: inline-block;\n  width: 2px;\n  height: 15px;\n  margin-left: 2px;\n  vertical-align: text-bottom;\n  background: var(--muse-primary);\n  animation: blink 0.9s steps(2) infinite;\n}\n\n@keyframes blink {\n  50% {\n    opacity: 0;\n  }\n}\n\n/* 打字点 */\n.typing-dots {\n  display: inline-flex;\n  gap: 5px;\n  padding: 4px 2px;\n}\n\n.typing-dots i {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--muse-primary);\n  animation: bounce 1.2s ease-in-out infinite;\n  opacity: 0.4;\n}\n\n.typing-dots i:nth-child(2) {\n  animation-delay: 0.18s;\n}\n\n.typing-dots i:nth-child(3) {\n  animation-delay: 0.36s;\n}\n\n@keyframes bounce {\n  0%,\n  80%,\n  100% {\n    transform: translateY(0);\n    opacity: 0.35;\n  }\n\n  40% {\n    transform: translateY(-7px);\n    opacity: 1;\n  }\n}\n\n/* ============================================\n   消息操作 — 可配置动作区\n   （按钮 / 下拉菜单 / 组合输入框 / 分隔线）\n   ============================================ */\n.message-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 5px;\n  padding: 0 2px;\n  opacity: 0;\n  transition: opacity 0.18s ease;\n}\n\n.message-row:hover .message-actions,\n.message-row:focus-within .message-actions {\n  opacity: 1;\n}\n\n@media (hover: none) {\n  .message-actions {\n    opacity: 1;\n  }\n}\n\n.mini-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  background: transparent;\n  border: none;\n  color: var(--muse-text-tertiary);\n  font-size: 12px;\n  vertical-align: middle;\n  font-family: var(--font-system);\n  cursor: pointer;\n  padding: 3px 8px;\n  border-radius: 6px;\n  line-height: 1;\n  transition: all 0.15s ease;\n}\n\n.mini-btn:hover:not(:disabled) {\n  color: var(--muse-primary);\n  background: var(--muse-primary-soft);\n}\n\n.mini-btn:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.mini-btn--active {\n  color: var(--muse-primary);\n  background: var(--muse-primary-soft);\n}\n\n.mini-btn--combo {\n  border-left: 1px solid var(--muse-border);\n  border-radius: 0 6px 6px 0;\n  background: var(--muse-primary-soft);\n  color: var(--muse-primary);\n  font-weight: 500;\n  white-space: nowrap;\n}\n\n.mini-btn--combo:hover:not(:disabled) {\n  background: var(--muse-primary);\n  color: #fff;\n}\n\n/* 分隔线 */\n.action-divider {\n  width: 1px;\n  height: 14px;\n  margin: auto 2px;\n  background: var(--muse-border-strong);\n  flex: 0 0 auto;\n}\n\n/* 下拉菜单 */\n.action-dropdown {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n}\n\n.action-arrow {\n  font-size: 10px;\n  opacity: 0.6;\n  transition: transform 0.15s ease;\n}\n\n.action-dropdown.open .action-arrow {\n  transform: rotate(180deg);\n}\n\n.action-menu {\n  position: absolute;\n  left: 0;\n  top: calc(100% + 4px);\n  z-index: 30;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 150px;\n  max-height: 260px;\n  overflow-y: auto;\n  padding: 5px;\n  background: #fff;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 10px;\n  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.14);\n}\n\n.action-menu-item {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  width: 100%;\n  padding: 7px 10px;\n  border: none;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--muse-text-secondary);\n  font-size: 12.5px;\n  font-family: var(--font-system);\n  text-align: left;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: background 0.15s ease, color 0.15s ease;\n}\n\n.action-menu-item:hover:not(:disabled) {\n  background: var(--muse-primary-soft);\n  color: var(--muse-primary);\n}\n\n.action-menu-item:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.action-menu-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* 组合输入框 + 按钮 */\n.action-input-group {\n  display: inline-flex;\n  align-items: stretch;\n  height: 26px;\n  background: #fff;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 7px;\n  overflow: hidden;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.action-input-group:focus-within {\n  border-color: var(--muse-primary);\n  box-shadow: 0 0 0 2px var(--muse-primary-ring);\n}\n\n.action-input {\n  width: 110px;\n  min-width: 60px;\n  height: 100%;\n  padding: 0 8px;\n  border: none;\n  outline: none;\n  background: transparent;\n  color: var(--muse-text);\n  font-size: 12px;\n  font-family: var(--font-system);\n}\n\n.action-input::placeholder {\n  color: var(--muse-text-tertiary);\n}\n\n.action-input:disabled {\n  opacity: 0.45;\n}\n\n/* 菜单过渡（兼容 Vue 2 / Vue 3 过渡类名） */\n.action-menu-enter-active,\n.action-menu-leave-active {\n  transition: opacity 0.15s ease, transform 0.15s ease;\n}\n\n.action-menu-enter,\n.action-menu-enter-from,\n.action-menu-leave-to {\n  opacity: 0;\n  transform: translateY(-4px);\n}\n\n/* 回到底部 */\n.scroll-bottom-btn {\n  position: sticky;\n  bottom: 14px;\n  left: 50%;\n  transform: translateX(-50%);\n  display: block;\n  margin: 0 auto;\n  width: 38px;\n  height: 38px;\n  border-radius: 50%;\n  border: 1px solid var(--muse-border-strong);\n  background: #fff;\n  color: var(--muse-text-secondary);\n  font-size: 16px;\n  cursor: pointer;\n  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.12);\n  transition: all 0.18s ease;\n}\n\n.scroll-bottom-btn:hover {\n  color: var(--muse-primary);\n  border-color: var(--muse-primary);\n  transform: translateX(-50%) translateY(-1px);\n}\n\n.fade-up-enter-active,\n.fade-up-leave-active {\n  transition: all 0.25s ease;\n}\n\n.fade-up-enter-from,\n.fade-up-leave-to {\n  opacity: 0;\n  transform: translateX(-50%) translateY(8px);\n}\n\n/* ============================================\n   Markdown 渲染样式\n   ============================================ */\n.bubble-content p {\n  margin: 0 0 8px;\n}\n\n.bubble-content p:last-child {\n  margin-bottom: 0;\n}\n\n.bubble-content h1,\n.bubble-content h2,\n.bubble-content h3,\n.bubble-content h4 {\n  font-size: 15px;\n  font-weight: 700;\n  margin: 14px 0 6px;\n  color: var(--muse-text);\n}\n\n.bubble-content ul,\n.bubble-content ol {\n  margin: 6px 0;\n  padding-left: 20px;\n}\n\n.bubble-content li {\n  margin: 3px 0;\n}\n\n.bubble-content code.md-inline {\n  background: rgba(0, 102, 204, 0.09);\n  color: var(--muse-primary-active);\n  border-radius: 5px;\n  padding: 1px 6px;\n  font-size: 13px;\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n}\n\n.bubble-content pre.md-code {\n  background: #0f172a;\n  color: #e2e8f0;\n  border-radius: 10px;\n  padding: 14px 16px;\n  overflow-x: auto;\n  margin: 10px 0;\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.bubble-content pre.md-code code {\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n  background: transparent;\n  color: inherit;\n}\n\n.bubble-content blockquote {\n  border-left: 3px solid var(--muse-primary);\n  margin: 8px 0;\n  padding: 2px 0 2px 12px;\n  color: var(--muse-text-secondary);\n}\n\n.bubble-content a {\n  color: var(--muse-primary);\n  text-decoration: none;\n  border-bottom: 1px solid rgba(0, 102, 204, 0.3);\n}\n\n.bubble-content a:hover {\n  color: var(--muse-primary-hover);\n}\n\n.bubble--user .bubble-content code.md-inline {\n  background: rgba(255, 255, 255, 0.18);\n  color: #fff;\n}\n\n.bubble--user .bubble-content pre.md-code {\n  background: rgba(0, 0, 0, 0.25);\n}\n\n/* ============================================\n   输入区\n   ============================================ */\n.chatbox-composer {\n  position: relative;\n  z-index: 10;\n  padding: 10px 20px 18px;\n}\n\n.composer-inner {\n  position: relative;\n  max-width: 880px;\n  margin: 0 auto;\n  background: var(--glass-bg);\n  border: 1px solid var(--muse-border);\n  border-radius: var(--radius-card);\n  box-shadow: var(--glass-shadow);\n  backdrop-filter: saturate(160%) blur(16px);\n  -webkit-backdrop-filter: saturate(160%) blur(16px);\n  padding: 12px 14px 10px;\n  transition: box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.composer-inner:focus-within {\n  border-color: var(--muse-primary);\n  box-shadow: 0 0 0 3px var(--muse-primary-ring), var(--glass-shadow-hover);\n}\n\n.composer-input {\n  width: 100%;\n  border: none;\n  outline: none;\n  resize: none;\n  background: transparent;\n  font-family: var(--font-system);\n  font-size: 14px;\n  line-height: 1.6;\n  color: var(--muse-text);\n  max-height: 180px;\n  padding: 2px 2px 6px;\n}\n\n.composer-input::placeholder {\n  color: var(--muse-text-tertiary);\n}\n\n.composer-footer {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-top: 2px;\n}\n\n.composer-hint {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-height: 26px;\n  min-width: 0;\n}\n\n.model-hint {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  font-size: 12px;\n  color: var(--muse-text-tertiary);\n  letter-spacing: 0.01em;\n}\n\n.streaming-hint {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  font-size: 12px;\n  color: var(--muse-primary);\n  font-weight: 500;\n}\n\n.hint-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: var(--muse-primary);\n  animation: pulse 1.2s ease-in-out infinite;\n}\n\n@keyframes pulse {\n  0%,\n  100% {\n    opacity: 0.35;\n    transform: scale(0.9);\n  }\n\n  50% {\n    opacity: 1;\n    transform: scale(1.1);\n  }\n}\n\n.composer-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.send-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: var(--muse-primary);\n  border: 1px solid var(--muse-primary);\n  color: #fff;\n  border-radius: 10px;\n  font-size: 13.5px;\n  font-weight: 600;\n  font-family: var(--font-system);\n  padding: 8px 18px;\n  cursor: pointer;\n  box-shadow: 0 2px 6px rgba(0, 102, 204, 0.32),\n    inset 0 1px 0 rgba(255, 255, 255, 0.2);\n  transition: all 0.18s cubic-bezier(0.34, 1.2, 0.64, 1);\n}\n\n.send-btn:hover:not(:disabled) {\n  background: var(--muse-primary-hover);\n  border-color: var(--muse-primary-hover);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 16px rgba(0, 102, 204, 0.36);\n}\n\n.send-btn:active:not(:disabled) {\n  transform: translateY(0) scale(0.98);\n  background: var(--muse-primary-active);\n}\n\n.message-body p {\n  margin: 0;\n}\n\n.send-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n  box-shadow: none;\n}\n\n.send-btn--stop {\n  background: #fff;\n  border-color: var(--muse-border-strong);\n  color: var(--muse-text-secondary);\n  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.05);\n}\n\n.send-btn--stop:hover {\n  background: #fff;\n  border-color: #dc2626;\n  color: #dc2626;\n  box-shadow: 0 3px 10px rgba(220, 38, 38, 0.16);\n}\n\n/* ============================================\n   子窗口层 — 同源内嵌 / 最小化 / 索引导航 / 可收起\n   ============================================ */\n.child-trigger-btn {\n  position: absolute;\n  top: -40px;\n  right: 6px;\n  z-index: 55;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 6px 10px 6px 12px;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 999px;\n  background: var(--glass-bg);\n  backdrop-filter: saturate(160%) blur(16px);\n  -webkit-backdrop-filter: saturate(160%) blur(16px);\n  box-shadow: var(--glass-shadow);\n  color: var(--muse-text-secondary);\n  font-family: var(--font-system);\n  font-size: 12.5px;\n  line-height: 1;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.child-trigger-btn:hover {\n  color: var(--muse-primary);\n  border-color: rgba(0, 102, 204, 0.35);\n  box-shadow: var(--glass-shadow-hover);\n  transform: translateY(-1px);\n}\n\n.child-trigger-btn--hidden {\n  opacity: 0.8;\n  border-style: dashed;\n}\n\n.child-trigger-count {\n  min-width: 18px;\n  height: 18px;\n  padding: 0 5px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 9px;\n  background: var(--muse-primary);\n  color: #fff;\n  font-size: 11px;\n  font-weight: 700;\n}\n\n.child-window-layer {\n  position: absolute;\n  right: 20px;\n  bottom: 168px;\n  width: min(840px, 64vw);\n  height: min(62vh, 620px);\n  min-height: 240px;\n  z-index: 50;\n  overflow: hidden;\n  background: var(--glass-bg);\n  border: 1px solid var(--muse-border-strong);\n  border-radius: var(--radius-card);\n  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.2), var(--glass-shadow-hover);\n  backdrop-filter: saturate(160%) blur(18px);\n  -webkit-backdrop-filter: saturate(160%) blur(18px);\n}\n\n.child-window-nav {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 42px;\n  box-sizing: border-box;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 0 10px;\n  border-bottom: 1px solid var(--muse-border);\n  background: rgba(255, 255, 255, 0.72);\n  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);\n}\n\n.child-nav-count {\n  flex: 0 0 auto;\n  height: 22px;\n  box-sizing: border-box;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 0 9px;\n  border-radius: 999px;\n  background: var(--muse-primary-soft);\n  color: var(--muse-primary-active);\n  font-size: 12px;\n  font-weight: 600;\n}\n\n.child-nav-count i {\n  font-size: 13px;\n}\n\n.child-nav-tabs {\n  flex: 1 1 auto;\n  min-width: 0;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  overflow-x: auto;\n  scrollbar-width: none;\n}\n\n.child-nav-tabs::-webkit-scrollbar {\n  display: none;\n}\n\n.child-nav-tab {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  max-width: 180px;\n  height: 28px;\n  box-sizing: border-box;\n  padding: 0 8px 0 6px;\n  border: 1px solid transparent;\n  border-radius: 9px;\n  background: transparent;\n  color: var(--muse-text-secondary);\n  font-family: var(--font-system);\n  font-size: 12.5px;\n  cursor: pointer;\n  transition: all 0.2s ease;\n}\n\n.child-nav-tab:hover {\n  background: var(--muse-primary-soft);\n  color: var(--muse-text);\n}\n\n.child-nav-tab.active {\n  background: var(--muse-primary-soft);\n  border-color: rgba(0, 102, 204, 0.28);\n  color: var(--muse-primary-active);\n  font-weight: 600;\n}\n\n.child-nav-tab.minimized {\n  opacity: 0.55;\n}\n\n.child-nav-index {\n  flex: 0 0 auto;\n  width: 18px;\n  height: 18px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  background: rgba(0, 102, 204, 0.1);\n  color: var(--muse-primary);\n  font-size: 11px;\n  font-weight: 700;\n}\n\n.child-nav-tab.active .child-nav-index {\n  background: var(--muse-primary);\n  color: #fff;\n}\n\n.child-nav-title {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.child-nav-mini {\n  flex: 0 0 auto;\n  color: var(--muse-text-tertiary);\n  font-size: 12px;\n}\n\n.child-nav-close {\n  flex: 0 0 auto;\n  width: 18px;\n  height: 18px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  color: var(--muse-text-tertiary);\n  font-size: 13px;\n  line-height: 1;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.child-nav-close:hover {\n  background: rgba(220, 38, 38, 0.12);\n  color: #dc2626;\n}\n\n.child-nav-actions {\n  flex: 0 0 auto;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.child-nav-btn {\n  width: 26px;\n  height: 26px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--muse-text-secondary);\n  font-size: 13px;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.child-nav-btn:hover:not(:disabled) {\n  background: rgba(15, 23, 42, 0.07);\n  color: var(--muse-text);\n}\n\n.child-nav-btn:disabled {\n  opacity: 0.35;\n  cursor: not-allowed;\n}\n\n.child-nav-btn--danger:hover:not(:disabled) {\n  background: rgba(220, 38, 38, 0.1);\n  color: #dc2626;\n}\n\n.child-window-body {\n  position: absolute;\n  top: 42px;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  overflow: hidden;\n  background: #fff;\n}\n\n.child-window-frame {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  border: none;\n  background: #fff;\n}\n\n.child-window-collapsed {\n  position: absolute;\n  top: 42px;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  color: var(--muse-text-tertiary);\n  font-size: 13px;\n}\n\n.child-collapsed-icon {\n  font-size: 30px;\n  opacity: 0.5;\n}\n\n.child-win-enter-active,\n.child-win-leave-active {\n  transition: all 0.28s cubic-bezier(0.34, 1.2, 0.64, 1);\n}\n\n.child-win-enter-from,\n.child-win-leave-to {\n  opacity: 0;\n  transform: translateY(14px) scale(0.97);\n}\n\n/* ============================================\n   知识库选择器 — 左上角查看 / 切换（名称 + ID）\n   ============================================ */\n.kb-bar {\n  position: relative;\n  z-index: 11;\n  padding: 12px 20px 0;\n}\n\n.kb-bar-inner {\n  max-width: 880px;\n  margin: 0 auto;\n  display: flex;\n  align-items: flex-start;\n}\n\n.kb-selector {\n  position: relative;\n  display: inline-flex;\n}\n\n.kb-trigger {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 12px 6px 8px;\n  background: var(--glass-bg);\n  border: 1px solid var(--muse-border);\n  border-radius: 12px;\n  cursor: pointer;\n  color: var(--muse-text-secondary);\n  font-family: var(--font-system);\n  box-shadow: var(--glass-shadow);\n  backdrop-filter: saturate(160%) blur(14px);\n  -webkit-backdrop-filter: saturate(160%) blur(14px);\n  transition: all 0.18s ease;\n}\n\n.kb-trigger:hover {\n  border-color: var(--muse-primary);\n  color: var(--muse-text);\n  box-shadow: var(--glass-shadow-hover);\n  transform: translateY(-1px);\n}\n\n.kb-trigger-icon {\n  flex: 0 0 auto;\n  width: 26px;\n  height: 26px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 8px;\n  background: var(--muse-primary-soft);\n  color: var(--muse-primary);\n  font-size: 14px;\n}\n\n.kb-trigger-text {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n}\n\n.kb-trigger-label {\n  font-size: 12px;\n  color: var(--muse-text-tertiary);\n  letter-spacing: 0.02em;\n  white-space: nowrap;\n}\n\n.kb-trigger-name {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--muse-text);\n  max-width: 180px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.kb-trigger-id {\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n  font-size: 11px;\n  color: var(--muse-text-tertiary);\n  background: rgba(15, 23, 42, 0.05);\n  border-radius: 6px;\n  padding: 1px 6px;\n  white-space: nowrap;\n}\n\n.kb-trigger-empty {\n  font-size: 13px;\n  color: var(--muse-text-tertiary);\n}\n\n.kb-trigger-arrow {\n  font-size: 11px;\n  opacity: 0.6;\n  transition: transform 0.18s ease;\n}\n\n.kb-trigger-arrow.open {\n  transform: rotate(180deg);\n}\n\n.kb-menu {\n  position: absolute;\n  top: calc(100% + 8px);\n  left: 0;\n  z-index: 60;\n  width: 320px;\n  max-width: calc(100vw - 32px);\n  background: #fff;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 14px;\n  box-shadow: 0 16px 48px rgba(15, 23, 42, 0.18);\n  overflow: hidden;\n  transform-origin: top left;\n}\n\n.kb-menu-header {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 10px;\n  border-bottom: 1px solid var(--muse-border);\n}\n\n.kb-menu-search {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 7px 10px;\n  background: var(--muse-bg);\n  border: 1px solid transparent;\n  border-radius: 9px;\n  color: var(--muse-text-tertiary);\n  transition: all 0.15s ease;\n}\n\n.kb-menu-search:focus-within {\n  background: #fff;\n  border-color: var(--muse-primary);\n  box-shadow: 0 0 0 3px var(--muse-primary-ring);\n  color: var(--muse-primary);\n}\n\n.kb-menu-search input {\n  flex: 1;\n  min-width: 0;\n  border: none;\n  outline: none;\n  background: transparent;\n  font-family: var(--font-system);\n  font-size: 13px;\n  color: var(--muse-text);\n}\n\n.kb-menu-search input::placeholder {\n  color: var(--muse-text-tertiary);\n}\n\n.kb-refresh {\n  flex: 0 0 auto;\n  width: 32px;\n  height: 32px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: 9px;\n  background: transparent;\n  color: var(--muse-text-secondary);\n  font-size: 15px;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.kb-refresh:hover {\n  background: var(--muse-primary-soft);\n  color: var(--muse-primary);\n}\n\n.kb-refresh .spinning {\n  animation: spin 0.8s linear infinite;\n}\n\n.kb-menu-body {\n  max-height: 300px;\n  overflow-y: auto;\n  padding: 6px;\n}\n\n.kb-menu-body::-webkit-scrollbar {\n  width: 6px;\n}\n\n.kb-menu-body::-webkit-scrollbar-thumb {\n  background: rgba(15, 23, 42, 0.14);\n  border-radius: 6px;\n}\n\n.kb-menu-status {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  padding: 28px 12px;\n  color: var(--muse-text-tertiary);\n  font-size: 13px;\n}\n\n.kb-menu-status i {\n  font-size: 22px;\n  opacity: 0.6;\n}\n\n.kb-spinner {\n  width: 18px;\n  height: 18px;\n  border: 2px solid rgba(0, 102, 204, 0.2);\n  border-top-color: var(--muse-primary);\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n}\n\n.kb-item {\n  position: relative;\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  width: 100%;\n  padding: 9px 10px;\n  border: none;\n  border-radius: 10px;\n  background: transparent;\n  text-align: left;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.kb-item:hover {\n  background: var(--muse-primary-soft);\n}\n\n.kb-item.active {\n  background: var(--muse-primary-soft);\n  box-shadow: inset 0 0 0 1px rgba(0, 102, 204, 0.18);\n}\n\n.kb-item-icon {\n  flex: 0 0 auto;\n  width: 28px;\n  height: 28px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 8px;\n  background: rgba(0, 102, 204, 0.08);\n  color: var(--muse-primary);\n  font-size: 14px;\n  margin-top: 1px;\n}\n\n.kb-item-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n\n.kb-item-name {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--muse-text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.kb-item.active .kb-item-name {\n  color: var(--muse-primary-active);\n}\n\n.kb-item-id {\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n  font-size: 11px;\n  color: var(--muse-text-tertiary);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.kb-item-check {\n  flex: 0 0 auto;\n  color: var(--muse-primary);\n  font-size: 15px;\n  margin-top: 6px;\n}\n\n.kb-item-copy {\n  flex: 0 0 auto;\n  color: var(--muse-text-tertiary);\n  font-size: 13px;\n  margin-top: 4px;\n  padding: 3px;\n  border-radius: 6px;\n  opacity: 0;\n  transition: opacity 0.15s ease, color 0.15s ease;\n}\n\n.kb-item:hover .kb-item-copy {\n  opacity: 1;\n}\n\n.kb-item-copy:hover {\n  color: var(--muse-primary);\n}\n\n.kb-menu-enter-active,\n.kb-menu-leave-active {\n  transition: opacity 0.18s ease, transform 0.18s ease;\n}\n\n.kb-menu-enter,\n.kb-menu-enter-from,\n.kb-menu-leave-to {\n  opacity: 0;\n  transform: translateY(-6px) scale(0.98);\n}\n\n/* 输入区下方的知识库提示胶囊 */\n.kb-hint {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  max-width: 180px;\n  padding: 2px 9px;\n  border: none;\n  border-radius: 999px;\n  background: rgba(0, 102, 204, 0.06);\n  color: var(--muse-text-tertiary);\n  font-size: 11px;\n  font-family: var(--font-system);\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.kb-hint i {\n  flex: 0 0 auto;\n  font-size: 11px;\n}\n\n.kb-hint span {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.kb-hint:hover {\n  color: var(--muse-primary);\n  background: var(--muse-primary-soft);\n}\n\n.kb-menu-divider {\n  height: 1px;\n  margin: 4px 6px;\n  background: var(--muse-border);\n}\n\n.kb-item--auto .kb-item-icon {\n  background: rgba(139, 92, 246, 0.1);\n  color: #8b5cf6;\n}\n\n/* ============================================\n   Skill 配置 — 右上角入口按钮 + 弹层\n   ============================================ */\n.skill-config-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  height: 30px;\n  padding: 0 12px;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 10px;\n  background: #fff;\n  color: var(--muse-text-secondary);\n  font-size: 12.5px;\n  font-weight: 500;\n  font-family: var(--font-system);\n  line-height: 1;\n  cursor: pointer;\n  white-space: nowrap;\n  transition: all 0.18s ease;\n}\n\n.skill-config-btn:hover {\n  border-color: var(--muse-primary);\n  color: var(--muse-primary);\n  transform: translateY(-1px);\n  box-shadow: 0 3px 10px rgba(0, 102, 204, 0.14);\n}\n\n.skill-config-btn i {\n  font-size: 13px;\n}\n\n.skill-config-mask {\n  position: absolute;\n  inset: 0;\n  z-index: 100;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n  background: rgba(15, 23, 42, 0.32);\n  backdrop-filter: blur(2px);\n  -webkit-backdrop-filter: blur(2px);\n}\n\n.skill-config-panel {\n  width: 440px;\n  max-width: 100%;\n  max-height: 100%;\n  overflow-y: auto;\n  background: #fff;\n  border-radius: 16px;\n  box-shadow: 0 24px 64px rgba(15, 23, 42, 0.24);\n  padding: 18px 20px 20px;\n}\n\n.skill-config-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 14px;\n}\n\n.skill-config-title {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  font-size: 15px;\n  font-weight: 600;\n  color: var(--muse-text);\n}\n\n.skill-config-title i {\n  color: var(--muse-primary);\n  font-size: 15px;\n}\n\n.skill-config-close {\n  width: 26px;\n  height: 26px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--muse-text-tertiary);\n  font-size: 20px;\n  line-height: 1;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.skill-config-close:hover {\n  background: rgba(15, 23, 42, 0.07);\n  color: var(--muse-text);\n}\n\n.skill-config-section-title {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--muse-text-tertiary);\n  letter-spacing: 0.02em;\n  margin: 4px 0 8px;\n}\n\n.skill-config-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-bottom: 16px;\n}\n\n.skill-config-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  border: 1px solid var(--muse-border);\n  border-radius: 10px;\n  background: var(--muse-card);\n}\n\n.skill-config-item-icon {\n  flex: 0 0 auto;\n  color: var(--muse-primary);\n  font-size: 14px;\n}\n\n.skill-config-name {\n  flex: 1;\n  min-width: 0;\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--muse-text);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.skill-config-id {\n  flex: 0 0 auto;\n  max-width: 180px;\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n  font-size: 11px;\n  color: var(--muse-text-tertiary);\n  background: rgba(15, 23, 42, 0.05);\n  border-radius: 6px;\n  padding: 1px 6px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.skill-config-item-fields {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.skill-config-edit {\n  width: 100%;\n  height: 28px;\n  padding: 0 8px;\n  border: 1px solid transparent;\n  border-radius: 7px;\n  background: #fff;\n  font-size: 12.5px;\n  font-family: var(--font-system);\n  color: var(--muse-text);\n  outline: none;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.skill-config-edit--id {\n  font-family: "JetBrains Mono", "Fira Code", Menlo, Consolas, monospace;\n  font-size: 11px;\n  color: var(--muse-text-secondary);\n}\n\n.skill-config-edit:hover {\n  border-color: var(--muse-border-strong);\n}\n\n.skill-config-edit:focus {\n  border-color: var(--muse-primary);\n  box-shadow: 0 0 0 3px var(--muse-primary-ring);\n}\n\n.skill-config-item-del {\n  flex: 0 0 auto;\n  width: 22px;\n  height: 22px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--muse-text-tertiary);\n  font-size: 15px;\n  line-height: 1;\n  cursor: pointer;\n  transition: all 0.15s ease;\n}\n\n.skill-config-item-del:hover {\n  background: rgba(220, 38, 38, 0.12);\n  color: #dc2626;\n}\n\n.skill-config-empty {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8px;\n  padding: 20px 12px;\n  margin-bottom: 16px;\n  color: var(--muse-text-tertiary);\n  font-size: 13px;\n}\n\n.skill-config-empty i {\n  font-size: 22px;\n  opacity: 0.6;\n}\n\n.skill-config-add {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.skill-config-field {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.skill-config-field > span {\n  font-size: 12px;\n  color: var(--muse-text-secondary);\n}\n\n.skill-config-field input {\n  height: 34px;\n  padding: 0 10px;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 9px;\n  background: #fff;\n  font-size: 13px;\n  font-family: var(--font-system);\n  color: var(--muse-text);\n  outline: none;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.skill-config-field input::placeholder {\n  color: var(--muse-text-tertiary);\n}\n\n.skill-config-field input:focus {\n  border-color: var(--muse-primary);\n  box-shadow: 0 0 0 3px var(--muse-primary-ring);\n}\n\n.skill-config-add-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  height: 34px;\n  border: none;\n  border-radius: 9px;\n  background: var(--muse-primary);\n  color: #fff;\n  font-size: 13px;\n  font-weight: 600;\n  font-family: var(--font-system);\n  cursor: pointer;\n  transition: all 0.18s ease;\n}\n\n.skill-config-add-btn:hover:not(:disabled) {\n  background: var(--muse-primary-hover);\n}\n\n.skill-config-add-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n.skill-config-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  margin-top: 18px;\n  padding-top: 14px;\n  border-top: 1px solid var(--muse-border);\n}\n\n.skill-config-cancel-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 34px;\n  padding: 0 16px;\n  border: 1px solid var(--muse-border-strong);\n  border-radius: 9px;\n  background: #fff;\n  color: var(--muse-text-secondary);\n  font-size: 13px;\n  font-weight: 500;\n  font-family: var(--font-system);\n  cursor: pointer;\n  transition: all 0.18s ease;\n}\n\n.skill-config-cancel-btn:hover {\n  border-color: var(--muse-primary);\n  color: var(--muse-primary);\n}\n\n.skill-config-confirm-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 34px;\n  padding: 0 18px;\n  border: none;\n  border-radius: 9px;\n  background: var(--muse-primary);\n  color: #fff;\n  font-size: 13px;\n  font-weight: 600;\n  font-family: var(--font-system);\n  cursor: pointer;\n  box-shadow: 0 2px 6px rgba(0, 102, 204, 0.32);\n  transition: all 0.18s ease;\n}\n\n.skill-config-confirm-btn:hover {\n  background: var(--muse-primary-hover);\n  transform: translateY(-1px);\n  box-shadow: 0 6px 16px rgba(0, 102, 204, 0.36);\n}\n\n.skill-config-enter-active,\n.skill-config-leave-active {\n  transition: opacity 0.18s ease;\n}\n\n.skill-config-enter,\n.skill-config-enter-from,\n.skill-config-leave-to {\n  opacity: 0;\n}\n\n/* ============================================\n   响应式\n   ============================================ */\n@media (max-width: 640px) {\n  .chatbox-navbar {\n    padding: 10px 12px 8px;\n  }\n\n  .chatbox-main {\n    padding: 10px 12px 14px;\n  }\n\n  .chatbox-composer {\n    padding: 8px 12px 12px;\n  }\n\n  .navbar-introduce {\n    display: none;\n  }\n\n  .message-body {\n    max-width: calc(100% - 50px);\n  }\n\n  .child-window-layer {\n    left: 12px;\n    right: 12px;\n    bottom: 120px;\n    width: auto;\n    height: min(68vh, 600px);\n  }\n\n  .child-nav-title {\n    max-width: 96px;\n  }\n\n  .child-trigger-btn {\n    top: -36px;\n    right: 8px;\n    padding: 5px 9px 5px 10px;\n    font-size: 12px;\n  }\n\n  .child-trigger-text {\n    display: none;\n  }\n\n  .kb-bar {\n    padding: 8px 12px 0;\n  }\n\n  .kb-trigger-name {\n    max-width: 110px;\n  }\n\n  .kb-menu {\n    width: 280px;\n  }\n}\n</style>\n\n\x3Cscript>export default \n          {"name":"ChatBox","data":function(\n) {\nreturn {\n      loading: false,\n      loadingText: "正在思考…",\n      inputPlaceholder: "输入你的问题，Enter 发送，Shift+Enter 换行",\n      isStreaming: false,\n      abortController: null,\n      messageActions: [\n        {\n          type: "button",\n          key: "copy",\n          label: "复制",\n          icon: "bi bi-copy",\n        },\n        {\n          type: "button",\n          key: "skill",\n          id: "4099f7a380a5898232e2e9e2c2459cd0",\n          label: "生成 PPT",\n          icon: "bi bi-copy",\n        },\n        {\n          type: "button",\n          key: "skill",\n          id: "1f8dc55b3d900b5313650399a55afe03",\n          label: "生成图表",\n          icon: "bi bi-copy",\n        },\n        {\n          type: "divider",\n        },\n        {\n          type: "dropdown",\n          key: "more",\n          label: "更多",\n          children: [\n            {\n              key: "regen",\n              label: "重新生成",\n              icon: "bi bi-arrow-repeat",\n            },\n          ],\n        },\n        {\n          type: "input-button",\n          key: "skill",\n          placeholder: "输入 AI Skill ID",\n          buttonText: ">",\n        },\n      ],\n      draft: "",\n      openMenuId: "",\n      showScrollHint: false,\n      messages: [],\n      title: "ChatBox",\n      introduce: "与 AI 对话功能。",\n      documentMeta: webCpu.documentMeta,\n      knowledgeBase: "",\n      icon: "聊",\n      exampleList: [\n        {\n          icon: "💡",\n          name: "帮我构思一个面向年轻人的低成本周末户外活动方案",\n        },\n        {\n          icon: "✍️",\n          name: "写一段小红书风格的夏季防晒霜种草文案，带 Emoji",\n        },\n        {\n          icon: "🧮",\n          name: "用通俗易懂的大白话和生活中的比喻，向新手解释什么是量子计算",\n        },\n        {\n          icon: "📋",\n          name: "提炼这篇 2000 字会议纪要的核心结论，并列出后续待办事项（Action Items）",\n        },\n      ],\n      query: [{"type":"button","key":"copy","label":"复制","icon":"bi bi-copy"},{"type":"button","key":"skill","id":"4099f7a380a5898232e2e9e2c2459cd0","label":"生成 PPT","icon":"bi bi-copy"},{"type":"button","key":"skill","id":"1f8dc55b3d900b5313650399a55afe03","label":"生成图表","icon":"bi bi-copy"},{"type":"button","key":"skill","id":"acaa43449534acd7da222ce192936e03","label":"添加知识库","icon":"bi bi-copy"},{"type":"divider"},{"type":"dropdown","key":"more","label":"更多","children":[{"key":"regen","label":"重新生成","icon":"bi bi-arrow-repeat"}]},{"type":"input-button","key":"skill","placeholder":"输入 AI Skill ID","buttonText":">"}],\n      content: {\n        inputText: "",\n        outputText: "",\n      },\n      accountData: {},\n      isSolo: WebTool.urlQuery(location.href, "solo"),\n      dataEditable: true,\n      defaultTemplate: "",\n      // 子窗口管理：当前窗口内打开的同源子页面（iframe），支持最小化与索引导航\n      childWindows: [],\n      activeChildId: "",\n      // 子窗口浮窗面板显示/隐藏（隐藏后仅保留输入框右上方的控制按钮）\n      childPanelVisible: true,\n      // 知识库选择：左上角查看 / 切换（名称 + ID 标识）\n      knowledgeBaseId: "",\n      kbLoading: false,\n      kbSearch: "",\n      kbMenuOpen: false,\n      // 知识库决策接口请求中（避免并发触发）；空知识库（knowledgeBaseId 为空）即自动决策模式\n      kbAnalyzing: false,\n      // Skill 配置弹层：登录态下用于查看 / 新增 messageActions 中的 skill 元素\n      skillConfigVisible: false,\n      skillDraft: {\n        name: "",\n        id: "",\n      }\n    };\n},"computed":{"canSend":function () {\n      return !!(this.draft && this.draft.trim()) && !this.isStreaming;\n    },"documentId":function () {\n      let documentId = this.query.documentId;\n      if (\n        !documentId &&\n        webCpu.currentCard &&\n        webCpu.currentCard.task &&\n        webCpu.currentCard.task.vueItem &&\n        webCpu.currentCard.task.vueItem.documentMeta\n      ) {\n        documentId = webCpu.currentCard.task.vueItem.documentMeta.documentId;\n      }\n      return documentId;\n    },"effectiveMessageActions":function () {\n      // 动作区配置优先级：props.messageActions > content.messageActions > 默认复制按钮\n      if (Array.isArray(this.messageActions) && this.messageActions.length) {\n        return this.messageActions;\n      }\n      if (\n        this.content &&\n        Array.isArray(this.content.messageActions) &&\n        this.content.messageActions.length\n      ) {\n        return this.content.messageActions;\n      }\n      return this.defaultMessageActions();\n    },"activeChildWindow":function () {\n      return this.childWindows.find((w) => w.id === this.activeChildId) || null;\n    },"isLoggedIn":function () {\n      // 登录态判断：localStorage 中的 token / userInfo\n      try {\n        if (\n          localStorage.getItem("token") ||\n          localStorage.getItem("access_token")\n        ) {\n          return true;\n        }\n        var raw =\n          localStorage.getItem("userInfo") ||\n          localStorage.getItem("user_info") ||\n          localStorage.getItem("user-info");\n        if (raw) {\n          try {\n            var u = JSON.parse(raw);\n            if (\n              u &&\n              (u.id || u.userId || u.token || u.mobile || u.name || u.nickName)\n            ) {\n              return true;\n            }\n          } catch (e) {\n            return true;\n          }\n        }\n      } catch (e) {\n        return false;\n      }\n      return false;\n    },"skillActionItems":function () {\n      // messageActions 中 key 为 skill 且带 id 的元素（名称 + ID）\n      var list = this.effectiveMessageActions || [];\n      return list.filter(function (item) {\n        return item && item.key === "skill" && item.id;\n      });\n    },"canAddSkill":function () {\n      return (\n        !!(this.skillDraft.name && this.skillDraft.name.trim()) &&\n        !!(this.skillDraft.id && this.skillDraft.id.trim())\n      );\n    }},"methods":{"confirmMessageActions":function () {\n      webCpu.mitt.emit("setDataMap", {\n        messageActions: this.messageActions,\n      });\n    },"actionHandler":function (value) {\n      // 消息动作接管处理：\n      // - skill：不再新开浏览器标签页，而是在当前窗口内打开同源子页面（inner iframe），\n      //   并纳入子窗口管理器：支持最小化；打开多个时仅展示当前激活窗口，\n      //   其余自动最小化，顶部“索引导航”可随时切换 / 恢复 / 关闭。\n      let item = (value && value.item) || value || {};\n      let message = (value && value.message) || value || {};\n\n      // 携带初始输入给子页面（同源 localStorage 传递）\n      if (message && message.content) {\n        localStorage.agentInput = message.content;\n      }\n\n      if (item.key === "skill") {\n        const url = this.buildChildWindowUrl(item, value);\n        if (url) {\n          this.openChildWindow({\n            url: url,\n            title: item.label || item.name || "子窗口",\n          });\n          // 返回 false 表示已接管该动作，跳过默认行为\n          return false;\n        }\n      }\n      return undefined;\n    },"buildChildWindowUrl":function (item, value) {\n      // 优先取按钮配置的 id，其次取组合输入框提交的 Skill ID（value 可能为字符串）\n      const id =\n        (item && item.id) ||\n        (value && typeof value === "object" && value.value) ||\n        (typeof value === "string" && value) ||\n        "";\n      if (!id) {\n        return "";\n      }\n      try {\n        // 以当前地址为基座，仅替换查询参数，保持同源开子页\n        const url = new URL(location.href.split("#")[0]);\n        url.searchParams.set("id", String(id));\n        url.searchParams.set("solo", "true");\n        url.searchParams.set("auto", "true");\n        return url.href;\n      } catch (e) {\n        return `${location.origin}?id=${encodeURIComponent(\n          id\n        )}&solo=true&auto=true`;\n      }\n    },"openChildWindow":function (opts) {\n      opts = opts || {};\n      const win = {\n        id:\n          "cw_" +\n          Date.now().toString(36) +\n          Math.random().toString(36).slice(2, 8),\n        title: opts.title || "子窗口",\n        url: opts.url || "",\n        minimized: false,\n        createdAt: Date.now(),\n      };\n      // 保证同时只显示一个子窗口：新窗口激活，其余全部最小化\n      this.childWindows.forEach((w) => {\n        w.minimized = true;\n      });\n      this.childWindows.push(win);\n      this.activeChildId = win.id;\n      // 新开任务时自动展开面板，确保用户能看到新窗口\n      this.childPanelVisible = true;\n      return win;\n    },"toggleChildPanel":function () {\n      if (!this.childWindows.length) {\n        return;\n      }\n      this.childPanelVisible = !this.childPanelVisible;\n    },"activateChildWindow":function (id) {\n      const win = this.childWindows.find((w) => w.id === id);\n      if (!win) {\n        return;\n      }\n      // 激活目标窗口，其余自动最小化\n      this.childWindows.forEach((w) => {\n        w.minimized = w.id !== id;\n      });\n      this.activeChildId = id;\n    },"minimizeChildWindow":function (id) {\n      const win = this.childWindows.find((w) => w.id === id);\n      if (!win || win.minimized) {\n        return;\n      }\n      win.minimized = true;\n      if (this.activeChildId === id) {\n        // 当前激活窗口被最小化后，自动激活最近一个未最小化窗口；没有则全部收起\n        const next = this.childWindows\n          .slice()\n          .reverse()\n          .find((w) => !w.minimized);\n        this.activeChildId = next ? next.id : "";\n      }\n    },"closeChildWindow":function (id) {\n      this.$confirm(\n        "关闭后无法重新打开，确认要关闭该窗口吗？",\n        webCpu.messages[lang].confirmDialogTitle,\n        {\n          confirmButtonText: webCpu.messages[lang].confirmYes,\n          cancelButtonText: webCpu.messages[lang].confirmNo,\n          type: "warning",\n        }\n      ).then(() => {\n        const idx = this.childWindows.findIndex((w) => w.id === id);\n        if (idx === -1) {\n          return;\n        }\n        this.childWindows.splice(idx, 1);\n        if (this.activeChildId === id) {\n          // 关闭激活窗口后，自动激活最近一个窗口，否则清空激活状态\n          const next = this.childWindows\n            .slice()\n            .reverse()\n            .find((w) => !w.minimized);\n          const fallback = this.childWindows[this.childWindows.length - 1];\n          const target = next || fallback;\n          if (target) {\n            target.minimized = false;\n            this.activeChildId = target.id;\n          } else {\n            this.activeChildId = "";\n          }\n        }\n      });\n    },"send":async function () {\n      const text = (this.draft || "").trim();\n      if (!text || this.isStreaming) {\n        return false;\n      }\n\n      this.pushMessage("user", text);\n      this.draft = "";\n      this.autoResize();\n      this.showScrollHint = false;\n\n      // 助手占位\n      const assistant = this.pushMessage("assistant", "", true);\n\n      this.startStream(assistant.id);\n    },"startStream":function (assistantId) {\n      this.isStreaming = true;\n      this.loading = true;\n\n      const query = Object.assign({}, this.query);\n      query.documentId = this.documentId;\n\n      query.context = this.buildContext();\n\n      this.abortController = aigcInterface.streamRequest(query, {\n        immediateFinish: false,\n        onMessage: (accumulated) => {\n          // 实时收到内容：逐字更新到消息气泡\n          this.updateMessage(assistantId, {\n            content: accumulated || "",\n          });\n          this.scrollToBottom();\n        },\n        onStreamFinished: (result) => {\n          this.updateMessage(assistantId, {\n            content: result || "",\n            streaming: false,\n          });\n          this.content.outputText = result || "";\n          this.finishStream();\n        },\n        onError: () => {\n          const msg = this.getMessage(assistantId);\n          if (msg && !msg.content) {\n            this.updateMessage(assistantId, {\n              content: "请求出现异常，请稍后重试。",\n            });\n          }\n          this.updateMessage(assistantId, {\n            streaming: false,\n          });\n          this.finishStream();\n        },\n        onAction: (action) => {\n          this.updateMessage(assistantId, {\n            streaming: false,\n          });\n          this.finishStream();\n          if (action === "LOGIN") {\n            aigcInterface.openLoginDialog(document.body, () => {\n              this.retryStream(assistantId);\n            });\n          } else if (action === "RECHARGE") {\n            aigcInterface.renderRechargeDialog(document.body);\n          }\n        },\n      });\n    },"retryStream":function (assistantId) {\n      this.updateMessage(assistantId, {\n        content: "",\n        streaming: true,\n      });\n      this.startStream(assistantId);\n    },"regenerate":function () {\n      // 正在输出时先停止当前流，再重新生成\n      if (this.isStreaming) {\n        this.stopStreaming();\n      }\n      const assistant = this.lastAssistant();\n      if (!assistant) {\n        return false;\n      }\n      const idx = this.messages.findIndex((m) => m.id === assistant.id);\n      if (idx === -1) {\n        return false;\n      }\n      // 移除最后一条助手回复（连同未完成的半截内容），\n      // 上下文里仍保留触发它的用户提问，随后对新占位消息重新发起请求\n      this.messages.splice(idx, 1);\n      this.content.outputText = "";\n      const newAssistant = this.pushMessage("assistant", "", true);\n      this.showScrollHint = false;\n      this.startStream(newAssistant.id);\n      return true;\n    },"finishStream":function () {\n      this.isStreaming = false;\n      this.loading = false;\n      this.abortController = null;\n      this.scrollToBottom();\n    },"stopStreaming":function () {\n      if (\n        this.abortController &&\n        typeof this.abortController.abort === "function"\n      ) {\n        this.abortController.abort();\n      }\n      const assistant = this.lastAssistant();\n      if (assistant) {\n        this.updateMessage(assistant.id, {\n          streaming: false,\n        });\n      }\n      this.finishStream();\n    },"pushMessage":function (role, content, streaming) {\n      const msg = {\n        id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),\n        role: role,\n        content: content || "",\n        time: Date.now(),\n        streaming: !!streaming,\n      };\n      this.messages.push(msg);\n      this.$nextTick(() => this.scrollToBottom());\n      // 返回响应式代理，确保后续流式更新能触发渲染\n      return this.messages[this.messages.length - 1];\n    },"getMessage":function (id) {\n      return this.messages.find((m) => m.id === id) || null;\n    },"updateMessage":function (id, patch) {\n      const idx = this.messages.findIndex((m) => m.id === id);\n      if (idx !== -1) {\n        Object.assign(this.messages[idx], patch);\n      }\n    },"lastAssistant":function () {\n      for (let i = this.messages.length - 1; i >= 0; i--) {\n        if (this.messages[i].role === "assistant") {\n          return this.messages[i];\n        }\n      }\n      return null;\n    },"buildContext":function () {\n      const history = this.messages\n        .filter((m) => m.content && String(m.content).trim())\n        .slice(-24);\n      return history\n        .map((m) => {\n          const who = m.role === "user" ? "用户" : "助手";\n          return `${who}：${m.content}`;\n        })\n        .join("\\n");\n    },"clearChat":function () {\n      if (this.isStreaming) {\n        this.stopStreaming();\n      }\n      this.messages = [];\n      this.content.outputText = "";\n      this.scrollToBottom(true);\n    },"useExample":function (d) {\n      this.draft = d.name || d.title || "";\n      this.$nextTick(() => {\n        this.autoResize();\n        if (this.$refs.textarea) {\n          this.$refs.textarea.focus();\n        }\n      });\n    },"defaultMessageActions":function () {\n      return [\n        {\n          type: "button",\n          key: "copy",\n          label: "复制",\n          icon: "bi bi-copy",\n          tooltip: "复制到剪贴板",\n        },\n      ];\n    },"isComboItem":function (item) {\n      if (!item || typeof item !== "object") {\n        return false;\n      }\n      return (\n        item.type === "input-button" ||\n        item.type === "inputButton" ||\n        item.type === "input" ||\n        item.type === "combo"\n      );\n    },"menuKey":function (m, item) {\n      return m.id + "::" + item.key;\n    },"isMenuOpen":function (m, item) {\n      return this.openMenuId === this.menuKey(m, item);\n    },"toggleActionMenu":function (m, item) {\n      const key = this.menuKey(m, item);\n      const wasOpen = this.openMenuId === key;\n      this.openMenuId = wasOpen ? "" : key;\n      this.dispatchMessageAction({\n        type: wasOpen ? "close" : "open",\n        key: item.key,\n        item: item,\n        message: m,\n      });\n    },"selectActionChild":function (m, parent, child) {\n      this.openMenuId = "";\n      this.dispatchMessageAction({\n        type: "select",\n        key: child.key,\n        parentKey: parent.key,\n        value: child.value !== undefined ? child.value : undefined,\n        item: child,\n        parent: parent,\n        message: m,\n      });\n    },"onActionInput":function (m, item, event) {\n      item.value = event.target.value;\n    },"submitCombo":function (m, item, event) {\n      if (item.disabled) {\n        return;\n      }\n      const group =\n        event && event.target && event.target.closest\n          ? event.target.closest(".action-input-group")\n          : null;\n      const input = group ? group.querySelector("input") : null;\n      this.dispatchMessageAction({\n        type: "submit",\n        key: item.key,\n        value: input ? input.value : "",\n        item: item,\n        message: m,\n      });\n    },"dispatchMessageAction":function (action) {\n      // 外部自定义处理：返回 false 表示已接管，跳过默认行为\n      const handled = this.actionHandler\n        ? this.actionHandler(action)\n        : undefined;\n      if (handled === false) {\n        return;\n      }\n      this.$emit("action", action);\n      this.applyDefaultAction(action);\n    },"applyDefaultAction":function (action) {\n      // 命中“点击 / 下拉选择”的内置默认动作\n      const isDefaultAction = (keys) =>\n        (action.type === "click" || action.type === "select") &&\n        keys.indexOf(action.key) !== -1;\n      // copy → 复制消息内容\n      if (isDefaultAction(["copy"])) {\n        this.copyText(action.message && action.message.content);\n      }\n      // regen / regenerate / 重新生成 → 重新生成最后一条助手回复\n      else if (isDefaultAction(["regen", "regenerate", "重新生成"])) {\n        this.regenerate();\n      }\n    },"copyText":function (text) {\n      if (WebTool && WebTool.copyString) {\n        WebTool.copyString(text);\n        this.$message({\n          type: "success",\n          message: "已复制到剪贴板。",\n        });\n      }\n    },"formatTime":function (ts) {\n      const d = new Date(ts || Date.now());\n      const pad = (n) => (n < 10 ? "0" + n : n);\n      return `${pad(d.getHours())}:${pad(d.getMinutes())}`;\n    },"onKeydown":function (e) {\n      if (\n        e.key === "Enter" &&\n        !e.shiftKey &&\n        !e.isComposing &&\n        !e.altKey &&\n        !e.ctrlKey &&\n        !e.metaKey\n      ) {\n        e.preventDefault();\n        this.send();\n      }\n    },"autoResize":function () {\n      this.$nextTick(() => {\n        const el = this.$refs.textarea;\n        if (!el) {\n          return;\n        }\n        el.style.height = "auto";\n        el.style.height = Math.min(el.scrollHeight, 180) + "px";\n      });\n    },"onScroll":function () {\n      const el = this.$refs.scrollContainer;\n      if (!el) {\n        return;\n      }\n      const distance = el.scrollHeight - el.scrollTop - el.clientHeight;\n      this.showScrollHint = distance > 120;\n    },"scrollToBottom":function (smooth) {\n      this.$nextTick(() => {\n        const el = this.$refs.scrollContainer;\n        if (!el) {\n          return;\n        }\n        el.scrollTo({\n          top: el.scrollHeight,\n          behavior: smooth ? "smooth" : "auto",\n        });\n      });\n    },"renderMarkdown":function (text) {\n      if (!text) {\n        return "";\n      }\n      const escapeHtml = (s) =>\n        String(s)\n          .replace(/&/g, "&amp;")\n          .replace(/</g, "&lt;")\n          .replace(/>/g, "&gt;");\n\n      const inline = (s) =>\n        escapeHtml(s)\n          .replace(/`([^`\\n]+)`/g, \'<code class="md-inline">$1</code>\')\n          .replace(/\\*\\*([^*]+)\\*\\*/g, "<strong>$1</strong>")\n          .replace(\n            /\\[([^\\]]+)\\]\\((https?:\\/\\/[^\\s)]+)\\)/g,\n            \'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>\'\n          );\n\n      const lines = String(text).split("\\n");\n      const out = [];\n      let codeBuf = null;\n      let listType = null;\n\n      const flushList = () => {\n        if (listType) {\n          out.push(`</${listType}>`);\n          listType = null;\n        }\n      };\n\n      for (let raw of lines) {\n        const line = raw.replace(/\\r$/, "");\n\n        // 代码块\n        if (/^```/.test(line.trim())) {\n          if (codeBuf === null) {\n            flushList();\n            codeBuf = [];\n          } else {\n            out.push(\n              `<pre class="md-code"><code>${escapeHtml(\n                codeBuf.join("\\n")\n              )}</code></pre>`\n            );\n            codeBuf = null;\n          }\n          continue;\n        }\n        if (codeBuf !== null) {\n          codeBuf.push(line);\n          continue;\n        }\n\n        const t = line.trim();\n        if (!t) {\n          flushList();\n          continue;\n        }\n\n        // 标题\n        let m = t.match(/^(#{1,4})\\s+(.*)$/);\n        if (m) {\n          flushList();\n          out.push(`<h4>${inline(m[2])}</h4>`);\n          continue;\n        }\n\n        // 引用\n        if (t.startsWith(">")) {\n          flushList();\n          out.push(\n            `<blockquote>${inline(t.replace(/^>\\s?/, ""))}</blockquote>`\n          );\n          continue;\n        }\n\n        // 无序列表\n        m = t.match(/^[-*+]\\s+(.*)$/);\n        if (m) {\n          if (listType !== "ul") {\n            flushList();\n            out.push(\'<ul class="md-list">\');\n            listType = "ul";\n          }\n          out.push(`<li>${inline(m[1])}</li>`);\n          continue;\n        }\n\n        // 有序列表\n        m = t.match(/^\\d+[.)]\\s+(.*)$/);\n        if (m) {\n          if (listType !== "ol") {\n            flushList();\n            out.push(\'<ol class="md-list">\');\n            listType = "ol";\n          }\n          out.push(`<li>${inline(m[1])}</li>`);\n          continue;\n        }\n\n        // 普通段落\n        flushList();\n        out.push(`<p>${inline(t)}</p>`);\n      }\n\n      if (codeBuf !== null) {\n        out.push(\n          `<pre class="md-code"><code>${escapeHtml(\n            codeBuf.join("\\n")\n          )}</code></pre>`\n        );\n      }\n      flushList();\n\n      return out.join("");\n    },"openSkillConfig":function () {\n      this.skillDraft = {\n        name: "",\n        id: "",\n      };\n      this.skillConfigVisible = true;\n    },"confirmSkillConfig":function () {\n      this.confirmMessageActions();\n      this.skillConfigVisible = false;\n      this.$message({\n        type: "success",\n        message: "Skill 操作配置已保存。",\n      });\n    },"addSkill":function () {\n      var name = (this.skillDraft.name || "").trim();\n      var id = (this.skillDraft.id || "").trim();\n      if (!name || !id) {\n        this.$message({\n          type: "warning",\n          message: "请填写 Skill 名称和 ID。",\n        });\n        return;\n      }\n      var exists = this.skillActionItems.some(function (item) {\n        return item.id === id;\n      });\n      if (exists) {\n        this.$message({\n          type: "warning",\n          message: "该 Skill ID 已存在。",\n        });\n        return;\n      }\n      var item = {\n        type: "button",\n        key: "skill",\n        id: id,\n        label: name,\n        icon: "bi bi-copy",\n      };\n      if (!Array.isArray(this.messageActions)) {\n        this.messageActions = [];\n      }\n      var list = this.messageActions;\n      var dividerIdx = list.findIndex(function (it) {\n        return it && it.type === "divider";\n      });\n      if (dividerIdx !== -1) {\n        list.splice(dividerIdx, 0, item);\n      } else {\n        list.push(item);\n      }\n      this.skillDraft = {\n        name: "",\n        id: "",\n      };\n      this.$message({\n        type: "success",\n        message: "已新增 Skill：" + name,\n      });\n    },"removeSkill":function (item) {\n      if (!Array.isArray(this.messageActions)) {\n        return;\n      }\n      var list = this.messageActions;\n      var idx = list.indexOf(item);\n      if (idx === -1 && item && item.id) {\n        idx = list.findIndex(function (it) {\n          return it && it.key === "skill" && it.id === item.id;\n        });\n      }\n      if (idx !== -1) {\n        list.splice(idx, 1);\n        this.$message({\n          type: "success",\n          message: "已删除该 Skill。",\n        });\n      }\n    }},"mounted":async function () {\n    this.content = this.content || {};\n\n    // Esc 关闭各类弹层\n    document.addEventListener("keydown", this.onGlobalKeydown);\n\n    // 平台传入的初始指令\n    if (aigcInterface && typeof aigcInterface.handleAgentInput === "function") {\n      aigcInterface.handleAgentInput(location.href, (str) => {\n        if (str) {\n          this.draft = str;\n          this.autoResize();\n          const auto = WebTool.urlQuery(location.href, "auto");\n          if (auto) {\n            this.send();\n          }\n        }\n      });\n    }\n  },"beforeDestroy":function () {\n    document.removeEventListener("keydown", this.onGlobalKeydown);\n  },"appMap":{"loginRegItem":{"url":"/mainApp/app/loginRegItem.js","key":"transweb_loginRegItem","cardName":"loginRegCard","dsl":{"data":{"position":"top","loginedMenu":[{"label":"⏱️ 历史记录","action":function (d, callback) {\n                dialogMap.openDocumentApp(\n                  webCpu.appConfig.aigcHistory,\n                  {\n                    data: {\n                      content: {\n                        isSolo: true,\n                      },\n                      query: {\n                        documentId: webCpu.currentVueItem.query.documentId,\n                      },\n                    },\n                  },\n                  {\n                    title: "⏱️ 历史记录",\n                    callback: callback,\n                  },\n                  {\n                    width: "100%",\n                    height: "100%",\n                  }\n                );\n              }}]}}}}};\x3C/script>\